<script setup>
import { reactive, watch, onMounted } from 'vue'
const props=defineProps({draftKey:{type:String,required:true},clearToken:{type:Number,default:0}})
const emit=defineEmits(['submit','cancel','cancel-request'])
const empty=()=>({name:'',email:'',phone:'',dateOfBirth:'',reason:''})
const form=reactive(empty()),errors=reactive({})
onMounted(()=>{try{Object.assign(form,JSON.parse(sessionStorage.getItem(props.draftKey)||'{}'))}catch{}})
watch(form,()=>{try{sessionStorage.setItem(props.draftKey,JSON.stringify(form))}catch{}},{deep:true})
watch(()=>props.clearToken,()=>{Object.assign(form,empty());Object.keys(errors).forEach(k=>delete errors[k]);try{sessionStorage.removeItem(props.draftKey)}catch{}})
function submit(){Object.keys(errors).forEach(k=>delete errors[k]);if(!form.name.trim())errors.name='Please enter your full name.';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email))errors.email='Enter a valid email address.';if(!/^\+?[0-9 ()-]{8,20}$/.test(form.phone))errors.phone='Enter a valid phone number.';if(!form.dateOfBirth)errors.dateOfBirth='Choose your date of birth.';else if(new Date(form.dateOfBirth)>new Date())errors.dateOfBirth='Date of birth cannot be in the future.';if(form.reason.trim().length<20)errors.reason='Please share at least 20 characters.';if(Object.keys(errors).length)return;emit('submit',{name:form.name.trim(),email:form.email.trim(),phone:form.phone.trim(),dateOfBirth:form.dateOfBirth,reason:form.reason.trim()})}
function cancel(){const dirty=Object.values(form).some(v=>String(v).trim());emit(dirty?'cancel-request':'cancel')}
</script>
<template><form class="form" @submit.prevent="submit" novalidate><header><span class="eyebrow">ATTENDEE DETAILS</span><h2>Complete your registration</h2><p>Your information is saved on this device as you type.</p></header><label>Full name <b>*</b><input v-model="form.name" autocomplete="name" :aria-invalid="!!errors.name" :class="{invalid:errors.name}"><small v-if="errors.name">{{errors.name}}</small></label><label>Email address <b>*</b><input v-model="form.email" type="email" autocomplete="email" :aria-invalid="!!errors.email" :class="{invalid:errors.email}"><small v-if="errors.email">{{errors.email}}</small></label><div class="row"><label>Phone number <b>*</b><input v-model="form.phone" type="tel" autocomplete="tel" :aria-invalid="!!errors.phone" :class="{invalid:errors.phone}"><small v-if="errors.phone">{{errors.phone}}</small></label><label>Date of birth <b>*</b><input v-model="form.dateOfBirth" type="date" :max="new Date().toISOString().slice(0,10)" :aria-invalid="!!errors.dateOfBirth" :class="{invalid:errors.dateOfBirth}"><small v-if="errors.dateOfBirth">{{errors.dateOfBirth}}</small></label></div><label>Why would you like to attend? <b>*</b><textarea v-model="form.reason" rows="4" maxlength="500" placeholder="Tell the organizer a little about your interest" :aria-invalid="!!errors.reason" :class="{invalid:errors.reason}"></textarea><span class="hint">{{form.reason.length}} / 500 characters (minimum 20)</span><small v-if="errors.reason">{{errors.reason}}</small></label><div class="actions"><button type="button" class="quiet" @click="cancel">Cancel</button><button type="submit" class="primary">Continue to confirmation →</button></div></form></template>
<style scoped>.form{display:grid;gap:1rem;padding:1.4rem;border:1px solid #eeedf4;border-radius:18px;background:#fff}.form header h2{margin:.35rem 0;font-size:1.35rem}.form header p{margin:0;color:#858397;font-size:.8rem}.eyebrow{color:#9997aa;font-size:.65rem;font-weight:800;letter-spacing:.15em}.form label{display:grid;gap:.4rem;color:#46445c;font-size:.76rem;font-weight:700}.form label b{display:inline;color:#c2415d}.form input,.form textarea{box-sizing:border-box;width:100%;min-height:44px;padding:.7rem .8rem;border:1px solid #e6e5ed;border-radius:10px;outline:none;color:#393750;background:#fff;font:inherit}.form textarea{resize:vertical}.form input:focus,.form textarea:focus{border-color:#8b75f2;box-shadow:0 0 0 3px #6748ed16}.form input.invalid,.form textarea.invalid{border-color:#d74d65}.form small{color:#b83b54;font-size:.7rem;font-weight:500}.hint{color:#9291a3;font-size:.68rem;font-weight:500}.row{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.actions{display:flex;justify-content:space-between;gap:.8rem;padding-top:.5rem}.actions button{min-height:44px;padding:0 1rem;border:0;border-radius:11px;font:inherit;font-size:.78rem;font-weight:750;cursor:pointer}.quiet{color:#68677a;background:#f3f3f8}.primary{color:white;background:#6748ed}@media(max-width:520px){.row{grid-template-columns:1fr}.actions{flex-direction:column-reverse}.actions button{width:100%}}</style>
